import { Collapsible as BaseCollapsible } from '@base-ui/react/collapsible';
import { ChevronDown } from 'lucide-react';
import { createContext, useContext, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { collapsibleVariants, type CollapsibleVariantProps } from './collapsible.variants';

type CollapsibleVariant = NonNullable<CollapsibleVariantProps['variant']>;
const CollapsibleContext = createContext<CollapsibleVariant>('subtle');

export interface CollapsibleProps extends Omit<BaseCollapsible.Root.Props, 'className'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** `subtle` (inline toggle) or `row` (full-width row with a divider, like an accordion item). */
  variant?: CollapsibleVariant;
}

/** A single show/hide section. Controlled with `open` + `onOpenChange`, or uncontrolled with `defaultOpen`. */
export function Collapsible({ variant = 'subtle', className, ...props }: CollapsibleProps) {
  return (
    <CollapsibleContext.Provider value={variant}>
      <BaseCollapsible.Root className={cn(collapsibleVariants({ variant }).root(), className)} {...props} />
    </CollapsibleContext.Provider>
  );
}

export interface CollapsibleTriggerProps extends Omit<BaseCollapsible.Trigger.Props, 'className'> {
  className?: string;
  ref?: Ref<HTMLButtonElement>;
  /** Show the rotating chevron. */
  showChevron?: boolean;
  children?: ReactNode;
}

/** The toggle button (aria-expanded, aria-controls). */
export function CollapsibleTrigger({ showChevron = true, className, children, ...props }: CollapsibleTriggerProps) {
  const variant = useContext(CollapsibleContext);
  const s = collapsibleVariants({ variant });
  return (
    <BaseCollapsible.Trigger className={cn(s.trigger(), className)} {...props}>
      {children}
      {showChevron && <ChevronDown size={variant === 'row' ? 16 : 15} className={s.chevron()} aria-hidden />}
    </BaseCollapsible.Trigger>
  );
}

export interface CollapsiblePanelProps extends Omit<BaseCollapsible.Panel.Props, 'className'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  children?: ReactNode;
}

/** The hidden content. Height animates; reduced motion turns the animation off. */
export function CollapsiblePanel({ className, children, ...props }: CollapsiblePanelProps) {
  const variant = useContext(CollapsibleContext);
  const s = collapsibleVariants({ variant });
  return (
    <BaseCollapsible.Panel className={s.panel()} {...props}>
      <div className={cn(s.content(), className)}>{children}</div>
    </BaseCollapsible.Panel>
  );
}

import { tv, type VariantProps } from '../../utils/tv';

export const collapsibleVariants = tv({
  slots: {
    root: 'flex flex-col',
    trigger: [
      'group inline-flex cursor-pointer items-center gap-2 rounded-md text-[13px] font-medium text-foreground transition-colors',
      'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
      'data-disabled:cursor-not-allowed data-disabled:opacity-50',
    ],
    chevron: [
      'shrink-0 text-muted-foreground transition-transform duration-200 motion-reduce:transition-none',
      'group-data-panel-open:rotate-180',
    ],
    panel: [
      'h-(--collapsible-panel-height) overflow-hidden transition-[height] duration-200 ease-out motion-reduce:transition-none',
      'data-starting-style:h-0 data-ending-style:h-0',
    ],
    content: 'pt-2 text-[13px] leading-relaxed text-muted-foreground text-pretty',
  },
  variants: {
    variant: {
      /** Compact inline toggle ("Show advanced settings"). */
      subtle: { trigger: 'h-8 -mx-2 px-2 hover:bg-secondary/60' },
      /** Full-width row with a divider, same family as Accordion. */
      row: {
        root: 'border-b border-border',
        trigger: 'w-full justify-between rounded-sm py-3.5 text-start hover:text-foreground/80',
        content: 'pt-0 pb-4',
      },
    },
  },
  defaultVariants: { variant: 'subtle' },
});

export type CollapsibleVariantProps = VariantProps<typeof collapsibleVariants>;

export {
  Collapsible,
  CollapsibleTrigger,
  CollapsiblePanel,
  type CollapsibleProps,
  type CollapsibleTriggerProps,
  type CollapsiblePanelProps,
} from './Collapsible';
export { collapsibleVariants, type CollapsibleVariantProps } from './collapsible.variants';
export { doc as collapsibleDoc } from './Collapsible.doc';

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Collapsible',
  group: 'Display',
  status: 'stable',
  description:
    'A single show/hide section: an inline toggle ("Advanced settings") or a full-width row in the Accordion family. The chevron rotates and the height animates. Compound parts: Collapsible, CollapsibleTrigger, CollapsiblePanel.',
  primitive: '@base-ui/react/collapsible',
  pattern: 'disclosure',
  keyboard: [
    ['Enter / Space', 'Expands or collapses the panel'],
    ['Tab', 'Moves focus from the trigger into the open panel content'],
  ],
  tokens: ['border', 'secondary', 'foreground', 'muted-foreground', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
